composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    command: "/parca --config-path=/etc/parca/parca.yaml --storage-path=/parca"
    environment:
      TZ: {{env.TZ}}
    volumes:
      - {{appDataPath}}/data:/parca
      - {{appDataPath}}/config:/etc/parca
